input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://example.org/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?name ?point ?class ?ref ?tsid WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
  OPTIONAL { ?z rdfs:label ?name . }
}
LIMIT 200

PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?s ?p ?o WHERE {
  ?s owl:sameAs "Zone_F3_Z01" .
} LIMIT 50

PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?ifc ?node WHERE {
  ?ifc <https://brickschema.org/schema/Brick/ref#ifcName> ?name .
  ?node owl:sameAs ?ifc .
  FILTER(CONTAINS(?name,"F3"))
} LIMIT 50

PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?a ?b WHERE {
  ?a owl:sameAs "urn:buildgraph:ifcref:c57f8ffb-d6ec-59be-8b08-2dff6de78f0b" .
  ?b owl:sameAs "urn:buildgraph:ifcref:c57f8ffb-d6ec-59be-8b08-2dff6de78f0b" .
}
